import { test, expect } from '@playwright/test';

test.describe('User Authentication Suite', () => {
  test('TC-001: Verify successful login with valid credentials', async ({ page }) => {
    // 1. Navigate to login page
    await page.goto('/login');
    await expect(page.getByRole('heading', { name: /sign in/i })).toBeVisible();

    // 2. Fill credentials
    await page.getByLabel(/email/i).fill('testuser@example.com');
    await page.getByLabel(/password/i).fill('ValidPass123!');
    await page.getByRole('button', { name: /sign in/i }).click();

    // 3. Verify redirection & dashboard state
    await expect(page).toHaveURL(/.*dashboard/);
    await expect(page.getByTestId('user-profile-header')).toBeVisible();
  });
});
